//! Simple command Tauri commands.
//!
//! Commands are sent to the session as CI (Command Input) frames:
//! `{"id":"<call-id>","name":"<command>","input":"<args-string>"}`.
//! Results arrive asynchronously as CO (Command Output) frames with the
//! same `id`, which the frontend renders (see reader.rs / Handlers.elm).
//! Uses the `send_cmd!` macro for fixed, argument-less commands.

use crate::commands::{send_cmd, SessionMap};
use crate::send_cmd;

use tauri::State;

// Simple commands with fixed text (generated by send_cmd! macro)
send_cmd!(alayacore_cancel, "cancel");
send_cmd!(alayacore_model_load, "model_load");
send_cmd!(alayacore_continue, "continue");
send_cmd!(alayacore_summarize, "summarize");

#[tauri::command]
pub async fn alayacore_model_set(
    session_id: String,
    model_id: u32,
    sessions: State<'_, SessionMap>,
) -> Result<(), String> {
    let map = sessions.0.lock().await;
    send_cmd(&map, &session_id, "model_set", &model_id.to_string())
        .await
        .map(|_| ())
}

#[tauri::command]
pub async fn alayacore_save(
    session_id: String,
    filename: String,
    sessions: State<'_, SessionMap>,
) -> Result<(), String> {
    let map = sessions.0.lock().await;
    send_cmd(&map, &session_id, "save", &filename).await.map(|_| ())
}

#[tauri::command]
pub async fn alayacore_fork(
    session_id: String,
    history_id: String,
    filename: String,
    sessions: State<'_, SessionMap>,
) -> Result<(), String> {
    let map = sessions.0.lock().await;
    let input = format!("{} {}", history_id, filename);
    send_cmd(&map, &session_id, "fork", &input).await.map(|_| ())
}

