#[tauri::command]
pub async fn alayacore_confirm(
    session_id: String,
    id: String,
    allowed: bool,
    sessions: State<'_, SessionMap>,
) -> Result<(), String> {
    let map = sessions.0.lock().await;
    let name = if allowed { "tool_confirm" } else { "tool_decline" };
    send_cmd(&map, &session_id, name, &id).await.map(|_| ())
}

